DROP POLICY IF EXISTS partner_mini_truck_pickup_profiles_operator ON public.partner_mini_truck_pickup_profiles;
CREATE POLICY partner_mini_truck_pickup_profiles_operator ON public.partner_mini_truck_pickup_profiles FOR ALL TO authenticated
  USING (public.caller_is_operator()) WITH CHECK (public.caller_is_operator());

-- mini_truck_pickup: repeating catalogue items (vehicles)
CREATE TABLE IF NOT EXISTS public.partner_mini_truck_pickup_items (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id   UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  service_id  UUID REFERENCES public.vendor_services(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL DEFAULT 0,
  category                     TEXT,
  payload_kg                   NUMERIC,
  load_dimensions              JSONB,
  body                         TEXT,
  count                        NUMERIC,
  driver_included              BOOLEAN,
  registration                 TEXT,
  access                       TEXT,
  photos                       TEXT[],
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mini_truck_pickup_items_service ON public.partner_mini_truck_pickup_items (service_id, position);

ALTER TABLE public.partner_mini_truck_pickup_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS partner_mini_truck_pickup_items_owner ON public.partner_mini_truck_pickup_items;
CREATE POLICY partner_mini_truck_pickup_items_owner ON public.partner_mini_truck_pickup_items FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_mini_truck_pickup_items.vendor_id AND v.profile_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_mini_truck_pickup_items.vendor_id AND v.profile_id = auth.uid()));

DROP POLICY IF EXISTS partner_mini_truck_pickup_items_operator ON public.partner_mini_truck_pickup_items;
CREATE POLICY partner_mini_truck_pickup_items_operator ON public.partner_mini_truck_pickup_items FOR ALL TO authenticated
  USING (public.caller_is_operator()) WITH CHECK (public.caller_is_operator());

COMMIT;

